import { MongoClient } from 'mongodb';

const uri = process.env.MONGODB_URI ?? 'mongodb://localhost:27017';
const client = new MongoClient(uri);

export const db = client.db('shop');

export async function closeDb() {
  await client.close();
}

import { ObjectId } from 'mongodb';
import { db, closeDb } from './db.mjs';

const products = db.collection('products');

try {
  const inserted = await products.insertOne({
    name: 'Monitor arm', price: 45, category: 'office', stock: 10, tags: ['desk']
  });
  console.log('inserted', inserted.insertedId instanceof ObjectId);

  const cheap = await products
    .find({ price: { $lt: 50 } }, { projection: { _id: 0, name: 1, price: 1 } })
    .sort({ price: 1 })
    .toArray();
  console.log(cheap);

  const updated = await products.updateOne({ _id: inserted.insertedId }, { $inc: { stock: -1 } });
  console.log('modified', updated.modifiedCount);

  const deleted = await products.deleteOne({ _id: inserted.insertedId });
  console.log('deleted', deleted.deletedCount);
} finally {
  await closeDb();
}

